-- ============================================================================
-- PARTIE 20 — Contenu du module 8 « Parents et alliance éducative » (3 séquences)
-- Source : Projet pédagogique Koalakids (relation de confiance, ouverture de la
-- crèche aux parents, personne ressource, respect des choix éducatifs, ajustements,
-- mécontentements, partage des doutes).
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 20.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Le partenariat avec les parents commence par la confiance : on leur laisse leur place de parents.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire comment créer une relation de confiance avec les parents (leur laisser leur place, les accueillir avec intérêt, se positionner comme personne ressource) et de repérer ce qui peut y faire obstacle.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 3, "attendu": "Partenariat avec les familles"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un parent du site avec qui la relation est facile, et à un autre avec qui elle l'est moins, sans les nommer."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Le partenariat avec les parents commence par la confiance : on leur laisse leur place de parents et on les accueille avec intérêt.", "idees": ["Créer une relation de confiance, c'est faire confiance aux parents avant de leur demander confiance : ne pas anticiper les difficultés ni décider à leur place de ce qui est bon pour eux. On ne connaît jamais un enfant ni une famille avant de les avoir rencontrés.", "Les parents sont toujours les bienvenus, circulent librement et peuvent rester aussi longtemps qu'ils le souhaitent. On leur dit bonjour et on s'intéresse à leur présence pour qu'ils ne se sentent ni transparents ni gênants. Les informations sur le fonctionnement de la crèche se donnent peu à peu, au fil des venues.", "Notre travail n'est pas d'apprendre aux enfants ou aux parents à se séparer, mais de soutenir le lien d'attachement qui les unit. Nous sommes des personnes ressources : pas de conseils, mais des informations qui leur permettent de faire leurs propres choix éducatifs."], "support": "Projet pédagogique Koalakids, « Que faire concrètement pour construire ce partenariat éducatif ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un échange vécu cette semaine avec un parent, sans le nommer. On analyse la façon dont on l'a accueilli, pas la personne.", "questions": ["Que s'est-il passé ? (ce que le parent a dit ou fait, ce que j'ai dit ou fait)", "Le parent s'est-il senti bienvenu et écouté ? Comment le sais-je ?", "Ai-je décidé à sa place ou anticipé des difficultés ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant, ni nom de parent, ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : dire bonjour à chaque parent et engager la conversation, même brièvement.", "Exemple : laisser un parent me montrer comment il s'y prend avant de donner mon avis.", "Exemple : m'asseoir près d'un parent sur l'espace de jeu pour échanger."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant ni de parent.", "Annoncer la séance 2/3 : analyse d'une situation vécue avec un parent, autour d'un choix, d'une demande ou d'un mécontentement."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 8 % 1/3 %';
-- FIN 20.1a

-- ---------------------------------------------------------------------------
-- 20.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Leur laisser leur place de parents", "paragraphes": ["Travailler en crèche ne signifie pas seulement accueillir des enfants : il s'agit aussi d'œuvrer **main dans la main avec leurs parents**, pour soutenir leur fonction parentale et favoriser le développement de leur enfant.", "Cette première séance pose un repère : avant de leur demander leur confiance, **on leur fait confiance**, on les accueille avec intérêt, et on leur laisse leur place."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Faire confiance d'abord :** ne pas anticiper les difficultés, ni décider à leur place de ce qui est bon pour eux.", "**Des parents bienvenus :** ils circulent librement, restent aussi longtemps qu'ils le souhaitent, et ne doivent se sentir ni transparents ni gênants.", "**Une personne ressource :** on ne donne pas de conseils, on soutient le lien parent-enfant et on informe pour que les parents fassent leurs propres choix."]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour construire un partenariat avec les parents.", "plutot": ["Accueillir les parents avec le sourire et de l'intérêt.", "Leur faire confiance sans anticiper les difficultés.", "Soutenir le lien entre l'enfant et ses parents.", "Être une personne ressource qui informe."], "eviter": ["Décider à leur place de ce qui est bon pour eux.", "Donner des conseils qu'ils n'ont pas demandés.", "Laisser un parent se sentir transparent ou gênant.", "Chercher à apprendre à l'enfant ou au parent à se séparer."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à un parent avec qui la relation est moins facile. Qu'est-ce que vous ne savez pas encore de lui et de sa façon d'être parent ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à garder une curiosité bienveillante.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Trois gestes avec un parent", "etapes": [{"titre": "Dire bonjour.", "texte": "Je m'intéresse à sa présence et je l'invite à venir jusqu'à moi."}, {"titre": "Écouter.", "texte": "Je donne du crédit à ce qu'il me dit de son enfant."}, {"titre": "Informer au besoin.", "texte": "Je réponds à ses questions, sans conseiller."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 8 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 20.1b

-- ---------------------------------------------------------------------------
-- 20.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Soutenir leurs choix, ajuster, entendre un mécontentement : on regarde comment on a fait équipe avec les parents.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable d'analyser une situation vécue avec un parent (un choix éducatif, une demande, un mécontentement) et de dire comment il a soutenu, ajusté ou écouté.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 3, "attendu": "Partenariat avec les familles"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un partenariat se vit aussi dans les moments difficiles : on soutient, on ajuste, on écoute.", "idees": ["On soutient les choix éducatifs des parents sans les juger ni les remettre en question, même s'ils ne correspondent pas à nos valeurs, sauf s'ils relèvent des violences faites aux enfants : dans ce cas, on en parle en équipe éducative et on signale. Si les parents changent d'avis, ce nouveau choix est toujours le bon.", "On sollicite les parents pour avoir leur avis sur les propositions faites pour leur enfant (par exemple dormir dans un lit bas, manger à table avec d'autres enfants), et on trouve les ajustements nécessaires quand ils nous sollicitent (par exemple coucher l'enfant plus tôt le midi).", "Un mécontentement trouve un écho et une réponse adaptée : la référente santé et accueil inclusif pour la santé de l'enfant, la responsable de la crèche pour les conditions d'accueil. On partage aussi nos propres doutes avec les parents."], "support": "Projet pédagogique Koalakids, « Respecter et soutenir les choix éducatifs des parents »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir une situation vécue cette semaine avec un parent (un choix éducatif, une demande, un mécontentement), sans le nommer. On analyse la pratique, pas la personne.", "questions": ["Qu'a dit ou demandé le parent ? Qu'ai-je répondu ?", "Ai-je soutenu son choix, cherché un ajustement, ou jugé ?", "La bonne personne a-t-elle été informée (cahier d'équipe, responsable, référente santé) ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant, ni nom de parent, ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : demander son avis à un parent avant de proposer un changement pour son enfant.", "Exemple : chercher avec un parent un ajustement qui l'aide à se sentir compris.", "Exemple : inscrire une demande de parent dans le cahier d'équipe le jour même."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant ni de parent.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur l'ouverture de la crèche aux parents."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 8 % 2/3 %';
-- FIN 20.2a

-- ---------------------------------------------------------------------------
-- 20.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Faire équipe, même quand c'est difficile", "paragraphes": ["Soutenir les choix des parents est facile quand ils ressemblent aux nôtres. Le partenariat se vit surtout **quand ils diffèrent**, quand une demande nous dérange, ou quand un parent est mécontent.", "Cette séance propose d'analyser une situation vécue avec un parent, en regardant ce que l'on a dit et fait, jamais la personne."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "On remet en cause un choix", "texte": "Une mère allaite encore son bébé et souhaite le faire sur place. Un collègue dit : « À cet âge, il faudrait arrêter. »", "analyse": "on soutient les choix éducatifs des parents sans les juger, même s'ils ne correspondent pas à nos valeurs. Les mamans qui allaitent sont invitées à le faire sur place autant que nécessaire."}, {"lettre": "B", "titre": "Une demande à ajuster", "texte": "Les parents de Lina aimeraient la coucher plus tôt le soir et demandent que sa sieste du midi commence plus tôt.", "analyse": "on cherche l'ajustement qui permette aux parents de se sentir compris, soutenus et non jugés. Coucher l'enfant plus tôt le midi, c'est lui donner son compte de sommeil et permettre à ses parents de le coucher plus tôt le soir."}, {"lettre": "C", "titre": "Un parent mécontent", "texte": "Un père dit, en venant chercher sa fille, qu'il est mécontent de la journée. Le professionnel répond : « Je n'y peux rien. »", "analyse": "un parent mécontent doit trouver un écho et une réponse adaptée. Pour la santé de l'enfant, la référente santé et accueil inclusif lui répond. Pour les conditions d'accueil, la responsable de la crèche le reçoit et l'écoute."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Face à un choix, une demande ou un mécontentement.", "plutot": ["Soutenir leurs choix sans les juger.", "Demander leur avis avant de proposer un changement pour leur enfant.", "Chercher l'ajustement qui les aide à se sentir compris.", "Écouter un mécontentement et passer le relais à la bonne personne."], "eviter": ["Remettre en question leurs choix.", "Décider seul d'un changement pour leur enfant.", "Ignorer ou minimiser un mécontentement.", "Garder pour soi nos doutes sur l'enfant."]}$kk$),
  (3,'reflexion',$kk${"question": "Y a-t-il un choix de parent qui vous met mal à l'aise ? Qu'est-ce qui vous aiderait à le soutenir quand même ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions avant de répondre à un parent", "etapes": [{"titre": "Qu'est-ce qu'il me demande ?", "texte": "Je reformule sa demande pour m'assurer de l'avoir comprise."}, {"titre": "Puis-je soutenir ou ajuster ?", "texte": "Je cherche ce qui peut se faire, sans juger."}, {"titre": "Qui doit le savoir ?", "texte": "Je l'inscris dans le cahier d'équipe ou je passe le relais."}], "note": "On analyse la pratique, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 8 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 20.2b

-- ---------------------------------------------------------------------------
-- 20.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Ouvrir la crèche aux parents, c'est leur faire une vraie place : s'asseoir, jouer, partager nos doutes.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée dans la relation avec un parent, et l'équipe a choisi une pratique commune pour ouvrir la crèche aux parents.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 3, "attendu": "Partenariat avec les familles"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Ouvrir la crèche aux parents, c'est leur faire une vraie place : s'asseoir, jouer, partager nos doutes.", "idees": ["Les parents peuvent rester aussi longtemps qu'ils le souhaitent. On pense à leur confort : porte-manteaux, sièges près des espaces de jeu, espace parental convivial si l'aménagement le permet. Les mamans qui allaitent sont invitées à le faire sur place.", "On permet aux parents d'interagir avec les enfants, sous notre regard et dans le respect de chaque enfant, et de participer à l'accompagnement du jeu ou aux sorties, voire de les initier.", "On partage nos doutes et nos questionnements avec les parents, et on leur demande au besoin de nous montrer comment ils s'y prennent : cela nous recentre sur l'enfant et tisse une confiance mutuelle."], "support": "Projet pédagogique Koalakids, « Installer une véritable ouverture de la crèche aux parents »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'est-ce que cela a changé dans la relation avec le parent, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant ni de parent.", "Tour de table : ce que je retiens du module 8. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 8 % 3/3 %';
-- FIN 20.3a

-- ---------------------------------------------------------------------------
-- 20.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Faire une vraie place aux parents", "paragraphes": ["Ouvrir la porte ne suffit pas. Pour que les parents se sentent chez eux, il faut **penser à leur confort**, les laisser rester, interagir avec les enfants, et leur parler aussi de nos doutes.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour ouvrir la crèche aux parents."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Une crèche ouverte :** parents bienvenus aussi longtemps qu'ils le souhaitent, avec porte-manteaux, sièges et espace parental si possible.", "**Une place auprès des enfants :** les parents interagissent avec eux, sous notre regard, et participent au jeu ou aux sorties.", "**Des doutes partagés :** on leur demande au besoin de nous montrer comment ils s'y prennent, pour se recentrer sur l'enfant."]}$kk$),
  (2,'reflexion',$kk${"question": "Qu'est-ce qui, dans votre crèche, dit aux parents qu'ils sont chez eux ? Qu'est-ce qui pourrait leur dire le contraire ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui rendrait la place des parents plus évidente.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple d'ouverture, que chacun fait de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 8 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 20.3b

-- ---------------------------------------------------------------------------
-- 20c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 8 %/3 %' order by m.ordre;
-- FIN 20c
